// retryingGateway.ts の charge 内
let sawTimeout = false;
for (let attempt = 1; ; attempt++) {
  try {
    return await this.#inner.charge(req);
  } catch (e) {
    if (e instanceof PaymentTimeoutError) sawTimeout = true;
    if (!isTransient(e) || attempt >= this.#maxAttempts) {
      // 途中で一度でも届いた可能性があれば「分からない」として返す
      throw sawTimeout ? new PaymentTimeoutError({ cause: e }) : e;
    }
    ...
  }
}

// orderService.ts の catch
if (e instanceof PaymentDeclinedError || e instanceof PaymentUnavailableError) {
  order.status = 'PAYMENT_FAILED';
  await this.#orders.save(order);
}
// Timeout は PENDING_PAYMENT のまま照合バッチに任せる
throw e;
